/* ============================================================
   script.min.js — ванильный JS сайта «Казачья Воля» (2026)
   1) Плавное появление страницы + снятие preload-режима
   2) Бургер-меню со stagger-анимацией пунктов
   3) Индикатор прогресса прокрутки + кнопка «наверх»
   4) Reveal-анимации и счётчики чисел (IntersectionObserver)
   5) Ленивая загрузка картинок (data-src)
   6) Параллакс декоративных пятен, 3D-tilt карточек,
      «магнитные» кнопки, эффект shine
   Всё уважает prefers-reduced-motion. Без внешних библиотек.
   ============================================================ */
(function () {
  'use strict';

  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var isTouch = matchMedia('(hover: none)').matches;

  /* ---------- 1. ПОЯВЛЕНИЕ СТРАНИЦЫ ---------- */
  // класс .js-ready навешивается inline-скриптом в <head> (header.php) —
  // именно он включает reveal-анимации. Если JS отключён — всё видно сразу.
  if (reduceMotion && typeof document.documentElement.style.setProperty === 'function') {
    document.documentElement.style.setProperty('--ease', 'linear');
  }

  /* ---------- 2. БУРГЕР-МЕНЮ (+ шторка, оверлей, stagger) ---------- */
  var burger = document.getElementById('burger');
  var nav = document.getElementById('nav');
  var overlay = document.getElementById('navOverlay');

  function setMenu(open) {
    if (!nav) return;
    nav.classList.toggle('is-open', open);
    if (overlay) overlay.classList.toggle('is-open', open);
    burger.setAttribute('aria-expanded', open ? 'true' : 'false');
    burger.setAttribute('aria-label', open ? 'Закрыть меню' : 'Открыть меню');
    document.body.style.overflow = open ? 'hidden' : '';
    // каскадное появление пунктов меню
    if (open && !reduceMotion) {
      nav.querySelectorAll('.nav-list a').forEach(function (a, i) {
        a.style.transitionDelay = (80 + i * 55) + 'ms';
        a.classList.add('in');
      });
    } else {
      nav.querySelectorAll('.nav-list a').forEach(function (a) {
        a.style.transitionDelay = '0ms';
        a.classList.remove('in');
      });
    }
  }

  if (burger && nav) {
    burger.addEventListener('click', function () {
      setMenu(!nav.classList.contains('is-open'));
    });
    if (overlay) overlay.addEventListener('click', function () { setMenu(false); });
    nav.addEventListener('click', function (e) {
      if (e.target.closest('a')) setMenu(false);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && nav.classList.contains('is-open')) {
        setMenu(false); burger.focus();
      }
    });
  }

  /* ---------- 2b. ВЛОЖЕННОЕ МЕНЮ (dropdown / аккордеон) ---------- */
  var isDesktop = function () { return window.matchMedia('(min-width: 992px)').matches; };
  document.querySelectorAll('.nav-item.has-sub').forEach(function (item) {
    var btn = item.querySelector(':scope > button.nav-parent');
    if (!btn) return;
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      var open = !item.classList.contains('is-open');
      // закрываем соседние пункты того же уровня
      var siblings = item.parentElement ? item.parentElement.querySelectorAll(':scope > .nav-item.has-sub.is-open') : [];
      siblings.forEach(function (s) {
        if (s !== item) { s.classList.remove('is-open'); var b = s.querySelector(':scope > button.nav-parent'); if (b) b.setAttribute('aria-expanded', 'false'); }
      });
      item.classList.toggle('is-open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  });
  // закрытие по клику вне шапки и по Esc
  document.addEventListener('click', function (e) {
    if (!e.target.closest('.site-header')) {
      document.querySelectorAll('.nav-item.has-sub.is-open').forEach(function (i) {
        i.classList.remove('is-open');
        var b = i.querySelector(':scope > button.nav-parent'); if (b) b.setAttribute('aria-expanded', 'false');
      });
    }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      document.querySelectorAll('.nav-item.has-sub.is-open').forEach(function (i) {
        i.classList.remove('is-open');
        var b = i.querySelector(':scope > button.nav-parent'); if (b) { b.setAttribute('aria-expanded', 'false'); b.focus(); }
      });
    }
  });

  /* ---------- 3. ШАПКА, ПРОГРЕСС ПРОКРУТКИ, «НАВЕРХ» ---------- */
  var header = document.querySelector('.site-header');
  var progress = document.getElementById('scrollProgress');
  var toTop = document.getElementById('toTop');

  function onScroll() {
    var y = window.scrollY || 0;
    if (header) header.classList.toggle('is-scrolled', y > 8);
    if (toTop) toTop.classList.toggle('is-visible', y > 600);
    if (progress) {
      var h = document.documentElement.scrollHeight - innerHeight;
      progress.style.transform = 'scaleX(' + (h > 0 ? Math.min(y / h, 1) : 0) + ')';
    }
  }
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });
  if (toTop) toTop.addEventListener('click', function () {
    window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
  });

  /* ---------- 4. REVEAL-АНИМАЦИИ И СЧЁТЧИКИ ---------- */
  var revealEls = [].slice.call(document.querySelectorAll(
    '.section, .hero, .event-row, .news-card, .gallery-item, .team-card, .rep-item, .number-card, .pull-quote, .cta-panel, .split-media, .prose, .page-hero .kicker, .page-hero .hero-sub'
  ));

  function countUp(el) {
    // находим первое число в тексте и плавно «докручиваем» его
    var m = el.textContent.match(/\d+/);
    if (!m) return;
    var target = parseInt(m[0], 10), dur = 1400, t0 = null;
    var text = el.textContent;
    function step(ts) {
      if (!t0) t0 = ts;
      var p = Math.min((ts - t0) / dur, 1);
      p = 1 - Math.pow(1 - p, 3); // easeOutCubic
      el.textContent = text.replace(m[0], String(Math.round(target * p)));
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  if ('IntersectionObserver' in window && !reduceMotion) {
    var io = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var el = entry.target;
        // внутри контейнеров с data-stagger добавляем задержку по индексу
        var parent = el.parentElement;
        if (parent && parent.hasAttribute('data-stagger')) {
          var idx = [].indexOf.call(parent.children, el);
          el.style.transitionDelay = Math.min(idx * 70, 420) + 'ms';
        }
        el.classList.add('is-visible');
        el.querySelectorAll('[data-countup]').forEach(countUp);
        obs.unobserve(el);
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
    revealEls.forEach(function (el) { el.classList.add('reveal-init'); io.observe(el); });
    /* Страховка: через 3 секунды показать всё, что Observer не «догнал»
       (например, при печати или нестандартном скролле) */
    setTimeout(function () {
      document.querySelectorAll('.reveal-init:not(.is-visible)').forEach(function (el) {
        var r = el.getBoundingClientRect();
        if (r.top < innerHeight + 80) el.classList.add('is-visible');
      });
    }, 3000);
  }

  /* ---------- 5. ЛЕНИВАЯ ЗАГРУЗКА ИЗОБРАЖЕНИЙ (data-src) ---------- */
  var lazyImages = [].slice.call(document.querySelectorAll('img[data-src]'));
  if ('IntersectionObserver' in window && lazyImages.length) {
    var lazyIO = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var img = entry.target;
        img.src = img.getAttribute('data-src');
        if (img.getAttribute('data-srcset')) img.srcset = img.getAttribute('data-srcset');
        img.addEventListener('load', function () { img.classList.add('is-loaded'); });
        obs.unobserve(img);
      });
    }, { rootMargin: '250px 0px' });
    lazyImages.forEach(function (img) { lazyIO.observe(img); });
  } else {
    lazyImages.forEach(function (img) { img.src = img.getAttribute('data-src'); });
  }

  /* ---------- 6a. ПАРАЛЛАКС ДЕКОРАТИВНЫХ ПЯТЕН ---------- */
  if (!reduceMotion) {
    var orbs = [].slice.call(document.querySelectorAll('[data-parallax]'));
    if (orbs.length) {
      var ticking = false;
      var parallax = function () {
        orbs.forEach(function (o) {
          var speed = parseFloat(o.getAttribute('data-parallax')) || 0.04;
          o.style.transform = 'translate3d(0,' + (window.scrollY * speed * -1) + 'px,0)';
        });
        ticking = false;
      };
      window.addEventListener('scroll', function () {
        if (!ticking) { ticking = true; requestAnimationFrame(parallax); }
      }, { passive: true });
      parallax();
    }
  }

  /* ---------- 6b. 3D-TILT КАРТОЧЕК (только для мыши) ---------- */
  if (!isTouch && !reduceMotion) {
    document.querySelectorAll('.tilt').forEach(function (card) {
      var max = parseFloat(card.getAttribute('data-tilt')) || 6;
      card.addEventListener('mousemove', function (e) {
        var r = card.getBoundingClientRect();
        var x = (e.clientX - r.left) / r.width - 0.5;
        var y = (e.clientY - r.top) / r.height - 0.5;
        card.style.transform = 'perspective(900px) rotateY(' + (x * max) + 'deg) rotateX(' + (-y * max) + 'deg) scale(1.015)';
      });
      card.addEventListener('mouseleave', function () {
        card.style.transform = '';
      });
    });

    /* ---------- 6c. «МАГНИТНЫЕ» КНОПКИ ---------- */
    document.querySelectorAll('.magnetic').forEach(function (btn) {
      btn.addEventListener('mousemove', function (e) {
        var r = btn.getBoundingClientRect();
        var dx = (e.clientX - r.left - r.width / 2) * 0.18;
        var dy = (e.clientY - r.top - r.height / 2) * 0.28;
        btn.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
      });
      btn.addEventListener('mouseleave', function () { btn.style.transform = ''; });
    });
  }

  /* ---------- 6d. ПОСТРОЧНОЕ РАСКРЫТИЕ ЗАГОЛОВКОВ (split-lines) ---------- */
  function splitLines(el) {
    var inner = el.firstElementChild || el;
    var text = (el.dataset.fullText || inner.textContent).trim();
    el.dataset.fullText = text;
    inner.textContent = '';
    // раскладываем по словам, затем режем по РЕАЛЬным визуальным строкам элемента
    var words = text.split(/\s+/);
    var probe = document.createElement('span');
    probe.style.cssText = 'position:absolute;visibility:hidden;left:-9999px;white-space:normal';
    inner.appendChild(probe);
    var lines = [], cur = '';
    words.forEach(function (w) {
      probe.textContent = cur ? cur + ' ' + w : w;
      if (probe.offsetHeight > probe.getAttribute('data-h') * 1 || (!cur && probe.offsetHeight)) {
        if (cur) { lines.push(cur); }
        cur = w;
        probe.setAttribute('data-h', String(probe.offsetHeight));
        probe.textContent = w;
      } else {
        cur = cur ? cur + ' ' + w : w;
        if (!probe.getAttribute('data-h')) probe.setAttribute('data-h', String(probe.offsetHeight || 1));
      }
    });
    if (cur) lines.push(cur);
    probe.remove();
    lines.forEach(function (ln, li) {
      var d = document.createElement('span'); d.className = 'line';
      var i = document.createElement('span'); i.className = 'line-inner'; i.textContent = ln;
      i.style.transitionDelay = Math.min(li * 0.12, 0.4) + 's';
      d.appendChild(i); inner.appendChild(d);
    });
    requestAnimationFrame(function () { el.classList.add('is-split'); });
  }
  // при смене ширины окна — пересобираем строки у уже разделённых заголовков
  var rsT = null;
  window.addEventListener('resize', function () {
    if (reduceMotion) return;
    clearTimeout(rsT);
    rsT = setTimeout(function () {
      document.querySelectorAll('.split-lines.is-split').forEach(splitLines);
    }, 200);
  });
  if (!reduceMotion && 'IntersectionObserver' in window) {
    var sio = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (e) {
        if (!e.isIntersecting) return;
        splitLines(e.target); obs.unobserve(e.target);
      });
    }, { threshold: 0.3 });
    document.querySelectorAll('.split-lines').forEach(function (el) { sio.observe(el); });
  }

  /* ---------- 6e. СВЕТОВОЕ ПЯТНО СЛЕДУЮЩЕЕ ЗА КУРСОРОМ (desktop) ---------- */
  if (!isTouch && !reduceMotion) {
    var glow = document.createElement('i');
    glow.setAttribute('aria-hidden', 'true');
    glow.style.cssText = 'position:fixed;width:520px;height:520px;left:0;top:0;z-index:0;' +
      'pointer-events:none;border-radius:50%;transform:translate(-50%,-50%);will-change:transform;' +
      'background:radial-gradient(circle,rgba(212,175,55,.10),transparent 60%)';
    document.body.appendChild(glow);
    var gx = 0, gy = 0, tx = 0, ty = 0, raf = null;
    window.addEventListener('pointermove', function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
    (function follow() {
      gx += (tx - gx) * 0.08; gy += (ty - gy) * 0.08;
      glow.style.transform = 'translate(' + (gx - 260) + 'px,' + (gy - 260) + 'px)';
      raf = requestAnimationFrame(follow);
    })();
  }

  /* ---------- 7. ПОИСК ПО САЙТУ (Ctrl+K / Cmd+K) ---------- */
  var searchBtn = document.getElementById('searchBtn');
  var searchModal = document.getElementById('searchModal');
  var searchInput = document.getElementById('searchInput');
  var searchResults = document.getElementById('searchResults');
  var searchIdx = [];
  try { searchIdx = JSON.parse(document.getElementById('searchIndex').textContent || '[]'); } catch (e) {}
  var selIx = -1;

  function norm(t) { return (t || '').toLowerCase().replace(/ё/g, 'е'); }
  function renderSearch() {
    if (!searchResults) return;
    var q = norm(searchInput.value.trim());
    selIx = -1;
    if (!q) { searchResults.innerHTML = ''; return; }
    var words = q.split(/\s+/);
    var hits = searchIdx.filter(function (it) {
      var hay = norm(it.t + ' ' + (it.x || ''));
      return words.every(function (w) { return hay.indexOf(w) !== -1; });
    }).slice(0, 8);
    searchResults.innerHTML = hits.map(function (h) {
      return '<li role="option"><a href="' + h.u + '"><span class="sr-kind">' + (h.k || '') + '</span>' +
        h.t + (h.x ? '<span class="sr-x">' + h.x + '</span>' : '') + '</a></li>';
    }).join('') || '<li><a tabindex="-1">Ничего не найдено</a></li>';
  }
  function openSearch() {
    if (!searchModal) return;
    searchModal.hidden = false;
    document.body.style.overflow = 'hidden';
    setTimeout(function () { searchInput.focus(); }, 30);
  }
  function closeSearch() {
    if (!searchModal) return;
    searchModal.hidden = true;
    document.body.style.overflow = '';
    if (searchBtn) searchBtn.focus();
  }
  if (searchBtn) searchBtn.addEventListener('click', openSearch);
  document.addEventListener('keydown', function (e) {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); searchModal && !searchModal.hidden ? closeSearch() : openSearch(); return; }
    if (!searchModal || searchModal.hidden) return;
    if (e.key === 'Escape') { closeSearch(); return; }
    var links = searchResults.querySelectorAll('a[href]');
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!links.length) return;
      selIx = (selIx + (e.key === 'ArrowDown' ? 1 : -1) + links.length) % links.length;
      links.forEach(function (l, i) { l.parentElement.classList.toggle('is-sel', i === selIx); });
      links[selIx].scrollIntoView({ block: 'nearest' });
    }
    if (e.key === 'Enter' && selIx >= 0 && links[selIx]) { e.preventDefault(); links[selIx].click(); }
    if (e.target === searchModal) closeSearch();
  });
  if (searchInput) searchInput.addEventListener('input', renderSearch);
  if (searchModal) searchModal.addEventListener('click', function (e) { if (e.target === searchModal) closeSearch(); });

  /* ---------- 8. LIGHTBOX ГАЛЕРЕИ ---------- */
  var lb = document.getElementById('lightbox');
  if (lb) {
    var lbImg = document.getElementById('lbImg'), lbCap = document.getElementById('lbCap');
    var galItems = Array.prototype.slice.call(document.querySelectorAll('.gallery-item img, figure img[data-full]'));
    var lbIx = 0;
    function showLb(i) {
      lbIx = (i + galItems.length) % galItems.length;
      var im = galItems[lbIx];
      lbImg.src = im.getAttribute('data-full') || im.src;
      lbImg.alt = im.alt || '';
      var cap = im.closest('figure') ? im.closest('figure').querySelector('figcaption') : null;
      lbCap.textContent = cap ? cap.textContent : '';
      lb.hidden = false; document.body.style.overflow = 'hidden';
    }
    galItems.forEach(function (im, i) {
      im.style.cursor = 'zoom-in';
      im.addEventListener('click', function () { showLb(i); });
    });
    document.getElementById('lbClose').addEventListener('click', function () { lb.hidden = true; document.body.style.overflow = ''; });
    document.getElementById('lbPrev').addEventListener('click', function () { showLb(lbIx - 1); });
    document.getElementById('lbNext').addEventListener('click', function () { showLb(lbIx + 1); });
    lb.addEventListener('click', function (e) { if (e.target === lb) { lb.hidden = true; document.body.style.overflow = ''; } });
    document.addEventListener('keydown', function (e) {
      if (lb.hidden) return;
      if (e.key === 'Escape') { lb.hidden = true; document.body.style.overflow = ''; }
      if (e.key === 'ArrowLeft') showLb(lbIx - 1);
      if (e.key === 'ArrowRight') showLb(lbIx + 1);
    });
  }

  /* ---------- 9. ФИЛЬТР НОВОСТЕЙ НА СТРАНИЦЕ «НОВОСТИ» ---------- */
  var newsFilter = document.getElementById('newsFilter');
  if (newsFilter) {
    newsFilter.addEventListener('input', function () {
      var q = norm(newsFilter.value.trim());
      var cards = document.querySelectorAll('#newsList .news-card');
      var shown = 0;
      cards.forEach(function (c) {
        var hit = !q || norm(c.getAttribute('data-title')).indexOf(q) !== -1;
        c.style.display = hit ? '' : 'none';
        if (hit) shown++;
      });
      var empty = document.getElementById('newsEmpty');
      if (empty) empty.hidden = shown > 0;
    });
  }

  /* ---------- 10. КОПИРОВАТЬ ССЫЛКУ (кнопки share) ---------- */
  document.querySelectorAll('.share-btn.copy').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var url = btn.getAttribute('data-copy') || location.href;
      var done = function () {
        var old = btn.textContent;
        btn.textContent = 'Скопировано ✔'; btn.classList.add('copied');
        setTimeout(function () { btn.textContent = old; btn.classList.remove('copied'); }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done, done);
      else {
        var ta = document.createElement('textarea'); ta.value = url; document.body.appendChild(ta);
        ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done();
      }
    });
  });

})();
